package ru.mytv.launcher;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

public class Scenes extends FrameLayout {
 final Handler ui=new Handler(Looper.getMainLooper());final Random random=new Random();final ImageView photo;final TextView clock;final boolean onlyClock,overlay;final int photoSeconds,moveSeconds,imageAlpha;volatile boolean running;volatile int generation;boolean showingPhoto;ExecutorService pool;int index;
 final String[] urls={"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1920&h=1080&q=80","https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1920&h=1080&q=80","https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=1920&h=1080&q=80"};
 public Scenes(Context c,boolean clocks){this(c,clocks,true);}
 public Scenes(Context c,boolean clocks,boolean respectMode){super(c);SharedPreferences p=SaverOptions.prefs(c);onlyClock=clocks||(respectMode&&p.getBoolean("clockMode",false));overlay=p.getBoolean("overlay",false);photoSeconds=Math.max(30,p.getInt("photo",60));moveSeconds=Math.max(5,p.getInt("move",15));int brightness=Math.max(10,Math.min(100,p.getInt("brightness",100)));imageAlpha=255*brightness/100;setBackgroundColor(Color.BLACK);photo=new ImageView(c);photo.setScaleType(ImageView.ScaleType.CENTER_CROP);addView(photo,new LayoutParams(-1,-1));clock=new TextView(c);clock.setTextSize(Math.max(24,Math.min(96,p.getInt("size",56))));int shade=204*brightness/100;clock.setTextColor(Color.rgb(shade,shade,shade));clock.setText(android.text.format.DateFormat.format("HH:mm",new Date()));addView(clock,new LayoutParams(-2,-2));index=random.nextInt(urls.length);}
 final Runnable time=new Runnable(){public void run(){if(!running)return;clock.setText(android.text.format.DateFormat.format("HH:mm",new Date()));clock.setVisibility(!showingPhoto||overlay?VISIBLE:INVISIBLE);clock.setAlpha(1f);ui.postDelayed(this,1000);}};
 final Runnable move=new Runnable(){public void run(){if(!running)return;if(getWidth()==0||getHeight()==0||clock.getWidth()==0||clock.getHeight()==0){ui.postDelayed(this,100);return;}int pad=Math.round(24*getResources().getDisplayMetrics().density);int maxX=Math.max(0,getWidth()-clock.getWidth()),maxY=Math.max(0,getHeight()-clock.getHeight());int minX=Math.min(pad,maxX),minY=Math.min(pad,maxY);int spanX=Math.max(0,maxX-2*pad),spanY=Math.max(0,maxY-2*pad);clock.animate().cancel();clock.animate().x(minX+random.nextInt(spanX+1)).y(minY+random.nextInt(spanY+1)).setDuration(1200).start();ui.postDelayed(this,moveSeconds*1000L);}};
 final Runnable next=new Runnable(){public void run(){if(!running)return;load();ui.postDelayed(this,photoSeconds*1000L);}};
 void start(){if(running)return;generation++;running=true;showingPhoto=false;clock.setVisibility(VISIBLE);clock.setAlpha(1f);pool=Executors.newSingleThreadExecutor();ui.post(time);ui.post(move);if(!onlyClock)ui.post(next);}
 void stop(){running=false;generation++;ui.removeCallbacksAndMessages(null);if(pool!=null)pool.shutdownNow();photo.animate().cancel();clock.animate().cancel();photo.setImageDrawable(null);}
 void load(){final int token=generation;final String url=urls[index++%urls.length];pool.submit(()->{Bitmap result=null;try{byte[] bytes=Updates.fetch(url,8388608);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth<1||o.outHeight<1)throw new Exception("Invalid image");o.inSampleSize=1;while(o.outWidth/o.inSampleSize>1920||o.outHeight/o.inSampleSize>1080)o.inSampleSize*=2;o.inJustDecodeBounds=false;o.inPreferredConfig=Bitmap.Config.RGB_565;result=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);}catch(Exception e){android.util.Log.w("MyTV","Landscape unavailable",e);}final Bitmap bitmap=result;ui.post(()->{if(!running||token!=generation){if(bitmap!=null)bitmap.recycle();return;}photo.animate().cancel();if(bitmap==null){showingPhoto=false;photo.setImageDrawable(null);clock.setVisibility(VISIBLE);}else{photo.setImageBitmap(bitmap);photo.setImageAlpha(imageAlpha);photo.setAlpha(0f);photo.animate().alpha(1f).setDuration(1200).withEndAction(()->{if(running&&token==generation){showingPhoto=true;clock.setVisibility(overlay?VISIBLE:INVISIBLE);}}).start();}});});}
}
